<?php
declare(strict_types=1); require __DIR__.'/app/bootstrap.php';
if(!users_exist($pdo)){ header('Location:/first-admin.php'); exit; }
$u=current_user($pdo);
$feed=$pdo->query("SELECT a.public_id,a.text_commentary,a.published_at,u.username,u.display_name,s.title,s.canonical_url FROM annotations a JOIN users u ON u.id=a.user_id JOIN sources s ON s.id=a.source_id WHERE a.visibility='public' AND a.status='published' ORDER BY a.published_at DESC LIMIT 30")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a><nav><?php if($u):?><a href="/research.php">Research</a><a href="/logout.php">Sign out</a><?php else:?><a href="/login.php">Log in</a><a href="/register.php">Sign up</a><?php endif?></nav></header><main class="layout"><section><div class="hero"><span class="eyebrow">THE ANNOTATED WEB</span><h1>See what people are saying about the page you’re on.</h1><p>Highlight, clip, annotate, preserve, discuss and research the web together.</p><a class="button" href="#extension">Add the Chrome sidebar</a></div><h2>Public annotations</h2><?php if(!$feed):?><div class="card empty">No public annotations yet. Install the extension and create the first one.</div><?php endif?><?php foreach($feed as $item):?><article class="card"><div class="meta"><strong><?=h($item['display_name'])?></strong> @<?=h($item['username'])?> · <?=h($item['published_at'])?></div><h3><?=h($item['title'] ?: $item['canonical_url'])?></h3><p><?=nl2br(h($item['text_commentary']))?></p><a href="/annotation.php?id=<?=h($item['public_id'])?>">View annotation</a> · <a href="<?=h($item['canonical_url'])?>" target="_blank" rel="noopener">Original source</a></article><?php endforeach?></section><aside><div class="card"><h3>Annotated V1</h3><p>Chrome sidebar + public website + team research foundation.</p></div></aside></main></body></html>
